INSERT INTO `blogs` (`id`, `title`, `ar_title`, `slug`, `summary`, `ar_summary`, `content`, `ar_content`, `category_id`, `audience_scope`, `featured_image`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Top 10 Tips for Learning English Fast', 'أفضل 10 نصائح لتعلم الإنجليزية بسرعة', 'top-10-tips-for-learning-english-fast', 'Simple habits that improve your English every day.', 'عادات بسيطة تُحسّن لغتك الإنجليزية يوميًا.', 'Build a daily routine, practice speaking, and immerse yourself in English media.', 'ابنِ روتينًا يوميًا، وتدرّب على التحدث، واغمر نفسك في وسائل الإعلام الإنجليزية.', 1, 'all', 'blog_images/learning-tips.jpg', NULL, '2026-05-14 08:03:51', '2026-05-14 08:03:51', '2026-05-14 08:03:51', NULL),
(2, 'Why Study in the UK?', 'لماذا الدراسة في المملكة المتحدة؟', 'why-study-in-the-uk', 'World-class education and a vibrant student experience.', 'تعليم عالمي وتجربة طلابية غنية.', 'The UK offers globally ranked institutions, diverse culture, and strong career pathways.', 'توفر المملكة المتحدة مؤسسات عالمية، وثقافة متنوعة، ومسارات مهنية قوية.', 2, 'all', 'blog_images/study-uk.jpg', NULL, '2026-05-14 08:03:51', '2026-05-14 08:03:51', '2026-05-14 08:03:51', NULL),
(3, 'Mastering English Grammar: A Beginner’s Guide', 'إتقان قواعد الإنجليزية: دليل للمبتدئين', 'mastering-english-grammar-beginners-guide', 'Understand the essentials without overwhelm.', 'افهم الأساسيات بدون تعقيد.', 'Start with tenses, sentence structure, and common grammar patterns.', 'ابدأ بالأزمنة وبناء الجملة وأنماط القواعد الشائعة.', 3, 'all', 'blog_images/grammar-guide.jpg', NULL, '2026-05-14 08:03:51', '2026-05-14 08:03:51', '2026-05-14 08:03:51', NULL),
(4, 'IELTS Preparation Checklist', 'قائمة التحضير لاختبار IELTS', 'ielts-preparation-checklist', 'A focused plan to prepare efficiently.', 'خطة مركّزة للتحضير بكفاءة.', 'Review band descriptors, take mock tests, and improve writing structure.', 'راجع معايير الدرجات، وأدِّ اختبارات تجريبية، وحسّن بنية الكتابة.', 4, 'all', 'blog_images/ielts-checklist.jpg', NULL, '2026-05-14 08:03:51', '2026-05-14 08:03:51', '2026-05-14 08:03:51', NULL),
(5, 'How English Skills Boost Your Career', 'كيف تعزز مهارات الإنجليزية مسارك المهني', 'how-english-skills-boost-your-career', 'Communicate better and access more opportunities.', 'تواصل أفضل واغتنم فرصًا أكثر.', 'English proficiency improves hiring prospects and global mobility.', 'إتقان الإنجليزية يرفع فرص التوظيف والتنقل عالميًا.', 5, 'all', 'blog_images/career-growth.jpg', NULL, '2026-05-14 08:03:51', '2026-05-14 08:03:51', '2026-05-14 08:03:51', NULL);
