INSERT INTO `destinations` (`id`, `country_id`, `slug`, `name`, `ar_name`, `region`, `ar_region`, `description`, `ar_description`, `image_url`, `short_pitch`, `ar_short_pitch`, `tuition_range`, `ar_tuition_range`, `visa_timeline`, `ar_visa_timeline`, `work_rights`, `ar_work_rights`, `scholarships_summary`, `ar_scholarships_summary`, `entry_req_gpa`, `ar_entry_req_gpa`, `entry_req_language`, `ar_entry_req_language`, `university_count`, `is_active`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 11, 'united-kingdom', 'United Kingdom', 'المملكة المتحدة', 'Europe', 'أوروبا', 'Study in United Kingdom and experience world-class education.', 'ادرس في المملكة المتحدة وتمتع بتعليم عالمي المستوى.', 'https://placehold.co/800x600?text=United+Kingdom', 'World-renowned degrees & post-study work rights.', 'شهادات عالمية وفرص عمل بعد التخرج.', 'GBP 15,000 - 35,000 / year', 'GBP 15,000 - 35,000 / سنة', '4-6 weeks', '4-6 أسابيع', 'Up to 3 years post-study', 'حتى 3 سنوات بعد التخرج', 'Government & University mandated', 'منح حكومية وجامعية', 'High school completion with competitive grades depending on program.', 'إكمال الثانوية العامة بدرجات تنافسية حسب البرنامج.', 'IELTS or equivalent English test is commonly required.', 'غالباً ما يُطلب اختبار IELTS أو ما يعادله في اللغة الإنجليزية.', 21, 1, '2026-05-14 08:04:18', '2026-05-14 08:04:18', NULL),
(2, 12, 'united-states', 'United States', 'الولايات المتحدة', 'North America', 'أمريكا الشمالية', 'Study in United States and access globally recognized education.', 'ادرس في الولايات المتحدة واستفد من تعليم معترف به عالمياً.', 'https://placehold.co/800x600?text=United+States', 'Top-ranked institutions and wide program choice.', 'مؤسسات عالية التصنيف وخيارات برامج واسعة.', 'USD 15,000 - 35,000 / year', 'USD 15,000 - 35,000 / سنة', '4-8 weeks', '4-8 أسابيع', 'Limited on-study work, OPT after graduation', 'عمل محدود أثناء الدراسة وبرنامج OPT بعد التخرج', 'University and merit scholarships', 'منح جامعية ومنح تفوق', 'Academic transcripts and competitive GPA vary by institution.', 'تختلف المتطلبات الأكاديمية والمعدل المطلوب حسب المؤسسة.', 'TOEFL, IELTS, or Duolingo may be accepted by many institutions.', 'قد تقبل العديد من المؤسسات TOEFL أو IELTS أو Duolingo.', 0, 1, '2026-05-14 08:04:18', '2026-05-14 08:04:18', NULL),
(3, 2, 'canada', 'Canada', 'كندا', 'North America', 'أمريكا الشمالية', 'Study in Canada with strong post-study options and student-friendly cities.', 'ادرس في كندا مع خيارات قوية بعد التخرج ومدن مناسبة للطلاب.', 'https://placehold.co/800x600?text=Canada', 'Quality education and welcoming multicultural communities.', 'تعليم عالي الجودة ومجتمعات متعددة الثقافات ومرحبة.', 'CAD 15,000 - 35,000 / year', 'CAD 15,000 - 35,000 / سنة', '4-6 weeks', '4-6 أسابيع', 'Strong post-study pathways', 'مسارات قوية بعد الدراسة', 'Public and institutional scholarships', 'منح حكومية ومؤسسية', 'A solid academic background is required for most programs.', 'يلزم سجل أكاديمي قوي لمعظم البرامج.', 'English proficiency such as IELTS or TOEFL is usually required.', 'عادةً ما يُطلب إثبات إجادة الإنجليزية مثل IELTS أو TOEFL.', 0, 1, '2026-05-14 08:04:18', '2026-05-14 08:04:18', NULL),
(4, 1, 'australia', 'Australia', 'أستراليا', 'Oceania', 'أوقيانوسيا', 'Study in Australia with excellent universities and a vibrant lifestyle.', 'ادرس في أستراليا مع جامعات متميزة ونمط حياة حيوي.', 'https://placehold.co/800x600?text=Australia', 'Excellent quality of life and strong career outcomes.', 'جودة حياة ممتازة وفرص مهنية قوية.', 'AUD 15,000 - 35,000 / year', 'AUD 15,000 - 35,000 / سنة', '4-6 weeks', '4-6 أسابيع', 'Post-study work options available', 'خيارات عمل متاحة بعد التخرج', 'University and government support', 'دعم جامعي وحكومي', 'Program entry depends on previous academic performance and documents.', 'يعتمد القبول على الأداء الأكاديمي السابق والوثائق المطلوبة.', 'IELTS, TOEFL, or PTE are common English requirements.', 'تعد IELTS أو TOEFL أو PTE من المتطلبات الشائعة للغة الإنجليزية.', 0, 1, '2026-05-14 08:04:18', '2026-05-14 08:04:18', NULL),
(5, 14, 'germany', 'Germany', 'ألمانيا', 'Europe', 'أوروبا', 'Study in Germany with strong academic reputation and research-led institutions.', 'ادرس في ألمانيا مع سمعة أكاديمية قوية ومؤسسات قائمة على البحث.', 'https://placehold.co/800x600?text=Germany', 'Research excellence and strong engineering ecosystem.', 'تميز بحثي وبيئة هندسية قوية.', 'EUR 5,000 - 20,000 / year', 'EUR 5,000 - 20,000 / سنة', '6-10 weeks', '6-10 أسابيع', 'Student work and post-study routes', 'العمل أثناء الدراسة ومسارات ما بعد التخرج', 'DAAD and university scholarships', 'منح DAAD ومنح جامعية', 'Relevant academic preparation and recognized qualifications are required.', 'يُطلب إعداد أكاديمي مناسب ومؤهلات معترف بها.', 'Programs may require English or German language proof depending on track.', 'قد تتطلب البرامج إثبات اللغة الإنجليزية أو الألمانية حسب المسار.', 0, 1, '2026-05-14 08:04:18', '2026-05-14 08:04:18', NULL),
(6, 4, 'ireland', 'Ireland', 'أيرلندا', 'Europe', 'أوروبا', 'Study in Ireland in an English-speaking environment with modern universities.', 'ادرس في أيرلندا ضمن بيئة ناطقة بالإنجليزية وجامعات حديثة.', 'https://placehold.co/800x600?text=Ireland', 'English-speaking study destination with strong tech links.', 'وجهة دراسية ناطقة بالإنجليزية مع ارتباط قوي بقطاع التقنية.', 'EUR 10,000 - 28,000 / year', 'EUR 10,000 - 28,000 / سنة', '4-8 weeks', '4-8 أسابيع', 'Post-study opportunities available', 'فرص متاحة بعد التخرج', 'Government and university scholarships', 'منح حكومية وجامعية', 'Admission decisions depend on previous academic performance.', 'تعتمد قرارات القبول على الأداء الأكاديمي السابق.', 'English proficiency is typically required for international students.', 'عادةً ما يُطلب إثبات إجادة الإنجليزية للطلاب الدوليين.', 0, 1, '2026-05-14 08:04:18', '2026-05-14 08:04:18', NULL),
(7, 15, 'netherlands', 'Netherlands', 'هولندا', 'Europe', 'أوروبا', 'Study in the Netherlands with internationally focused programs.', 'ادرس في هولندا مع برامج ذات توجه دولي.', 'https://placehold.co/800x600?text=Netherlands', 'Innovative education and international classrooms.', 'تعليم مبتكر وفصول دراسية دولية.', 'EUR 8,000 - 24,000 / year', 'EUR 8,000 - 24,000 / سنة', '4-6 weeks', '4-6 أسابيع', 'Post-study orientation year available', 'سنة توجيهية متاحة بعد التخرج', 'Holland Scholarship and university funding', 'منحة هولندا وتمويل جامعي', 'Recognized school or university qualifications are needed.', 'يلزم تقديم مؤهلات مدرسية أو جامعية معترف بها.', 'English proficiency evidence is required for English-taught programs.', 'يُطلب إثبات إجادة الإنجليزية للبرامج التي تدرّس بالإنجليزية.', 0, 1, '2026-05-14 08:04:18', '2026-05-14 08:04:18', NULL),
(8, 16, 'malaysia', 'Malaysia', 'ماليزيا', 'Asia', 'آسيا', 'Study in Malaysia with affordable tuition and modern campuses.', 'ادرس في ماليزيا برسوم مناسبة وحرم جامعي حديث.', 'https://placehold.co/800x600?text=Malaysia', 'Affordable international education in Asia.', 'تعليم دولي ميسور التكلفة في آسيا.', 'MYR 12,000 - 35,000 / year', 'MYR 12,000 - 35,000 / سنة', '3-6 weeks', '3-6 أسابيع', 'Limited student work availability', 'توفر محدود للعمل الطلابي', 'Institutional and partner scholarships', 'منح مؤسسية ومنح الشركاء', 'Most institutions require valid academic transcripts and supporting documents.', 'تطلب معظم المؤسسات سجلات أكاديمية ووثائق داعمة سارية.', 'English proficiency or equivalent pathway evidence may be required.', 'قد يُطلب إثبات إجادة الإنجليزية أو ما يعادلها.', 0, 1, '2026-05-14 08:04:18', '2026-05-14 08:04:18', NULL);
