INSERT INTO `faqs` (`id`, `category`, `ar_category`, `question`, `ar_question`, `answer`, `ar_answer`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Getting Started', 'البدء', 'Getting Started', 'Getting Started', 'Getting Started', 'Getting Started', 0, 1, '2026-04-28 05:05:16', '2026-04-28 05:05:16'),
(2, 'General', 'عام', 'How do I choose the right English course?', 'كيف أختار دورة اللغة الإنجليزية المناسبة؟', 'Start with your goal, budget, destination, and preferred study intensity. Compare course type, weekly lessons, and accommodation options before booking.', 'ابدأ بتحديد هدفك وميزانيتك والوجهة المناسبة ومستوى الدراسة الذي تفضله. قارن بين نوع الدورة وعدد الدروس الأسبوعية وخيارات السكن قبل الحجز.', 1, 1, '2026-05-14 08:03:52', '2026-05-14 08:03:52'),
(3, 'Booking', 'الحجز', 'What is included in the total booking price?', 'ماذا يشمل إجمالي سعر الحجز؟', 'The final total may include tuition, registration fees, accommodation, airport pickup, insurance, and any selected add-ons depending on the school and package.', 'قد يشمل السعر النهائي الرسوم الدراسية ورسوم التسجيل والسكن والاستقبال من المطار والتأمين وأي خدمات إضافية يتم اختيارها بحسب المعهد أو الباقة.', 2, 1, '2026-05-14 08:03:52', '2026-05-14 08:03:52'),
(4, 'Accommodation', 'السكن', 'Can I book a course without accommodation?', 'هل يمكنني حجز الدورة بدون سكن؟', 'Yes. Many schools allow you to continue without accommodation if you prefer to arrange your own stay.', 'نعم، تتيح لك العديد من المعاهد متابعة الحجز بدون سكن إذا كنت تفضل ترتيب إقامتك بنفسك.', 3, 1, '2026-05-14 08:03:52', '2026-05-14 08:03:52'),
(5, 'Travel', 'السفر', 'Do you help with airport pickup and arrival support?', 'هل تقدمون خدمة الاستقبال من المطار والمساعدة عند الوصول؟', 'Yes. Many partner schools provide airport pickup options, and you can add them during the booking process when available.', 'نعم، توفر العديد من المعاهد الشريكة خيارات الاستقبال من المطار، ويمكنك إضافتها أثناء عملية الحجز عند توفرها.', 4, 1, '2026-05-14 08:03:52', '2026-05-14 08:03:52'),
(6, 'Payments', 'الدفع', 'Can I compare offers before making a payment?', 'هل يمكنني مقارنة العروض قبل الدفع؟', 'Yes. You can compare schools, course details, and pricing before confirming your reservation.', 'نعم، يمكنك مقارنة المعاهد وتفاصيل الدورات والأسعار قبل تأكيد الحجز.', 5, 1, '2026-05-14 08:03:52', '2026-05-14 08:03:52'),
(7, 'Agents', 'الوكلاء', 'Can an agent submit bookings on behalf of students?', 'هل يمكن للوكيل تقديم الحجوزات نيابة عن الطلاب؟', 'Yes. Agent users can manage student leads and submit bookings on behalf of their students through the platform workflow.', 'نعم، يمكن لمستخدمي الوكلاء إدارة الطلاب المحتملين وتقديم الحجوزات نيابة عن طلابهم من خلال سير العمل داخل المنصة.', 6, 1, '2026-05-14 08:03:52', '2026-05-14 08:03:52');
